#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_update_non_head_node_ct_and_tat_only(void) {
    // Build a linked list with at least two nodes.
    // The target node is NOT the head.
    // We will update with non-zero ct and tat, and zero wt.
    // This matches path 3 conditions:
    // - ptr != NULL && ptr->ID != id (head check fails, enter while loop)
    // - ct != 0 (true) -> update CT
    // - wt != 0 (false) -> skip WT
    // - tat != 0 (true) -> update TAT

    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;

    node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial state (all CT, WT, TAT are zero after insert)
    node *ptr = root;
    while (ptr != NULL) {
        TEST_ASSERT_EQUAL_INT(0, ptr->CT);
        TEST_ASSERT_EQUAL_INT(0, ptr->WT);
        TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
        ptr = ptr->next;
    }

    // Update node with ID 2 (non-head) with ct=100, wt=0, tat=200
    update(&root, 2, 100, 0, 200);

    // Verify only node with ID 2 is updated, others unchanged
    ptr = root;
    while (ptr != NULL) {
        if (ptr->ID == 2) {
            TEST_ASSERT_EQUAL_INT(100, ptr->CT);
            TEST_ASSERT_EQUAL_INT(0, ptr->WT);   // wt was zero, should remain zero
            TEST_ASSERT_EQUAL_INT(200, ptr->TAT);
        } else {
            TEST_ASSERT_EQUAL_INT(0, ptr->CT);
            TEST_ASSERT_EQUAL_INT(0, ptr->WT);
            TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
        }
        ptr = ptr->next;
    }

    // Cleanup
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_update_non_head_node_ct_and_tat_only);
    return UNITY_END();
}

